-- from supabase/migrations/20261008190000_location_precision_phase2.sql
CREATE OR REPLACE FUNCTION public.hrms_office_relation(
  p_office_id uuid, p_latitude double precision, p_longitude double precision, p_accuracy_m double precision
) RETURNS jsonb
LANGUAGE plpgsql
STABLE
SET search_path = public, pg_temp
AS $$
DECLARE
  v_office record;
  v_radius double precision;
  v_distance double precision;
BEGIN
  SELECT o.latitude, o.longitude, coalesce(o.allowed_radius_meters, o.attendance_radius) AS radius
  INTO v_office FROM public.offices o WHERE o.id = p_office_id;
  IF NOT FOUND OR v_office.latitude IS NULL OR v_office.longitude IS NULL
     OR p_latitude IS NULL OR p_longitude IS NULL THEN
    RETURN jsonb_build_object('state', 'UNKNOWN');
  END IF;
  v_radius := greatest(coalesce(v_office.radius, 200), 50);
  v_distance := public.tracking_distance_metres(v_office.latitude, v_office.longitude, p_latitude, p_longitude);
  RETURN jsonb_build_object(
    'state', CASE
      WHEN v_distance - least(coalesce(p_accuracy_m, 100), 50) <= v_radius THEN 'INSIDE'
      WHEN v_distance - coalesce(p_accuracy_m, 0) > v_radius + 150 THEN 'OUTSIDE'
      ELSE 'NEAR' END,
    'distance_m', round(v_distance::numeric, 1),
    'radius_m', v_radius);
END;
$$;

-- from supabase/migrations/20261008190000_location_precision_phase2.sql
CREATE OR REPLACE FUNCTION public.hrms_field_visit_site(
  p_visit_id uuid,
  OUT latitude double precision, OUT longitude double precision, OUT radius_m double precision
)
LANGUAGE plpgsql
STABLE
SET search_path = public, pg_temp
AS $$
DECLARE
  v_visit public.field_visits%rowtype;
  v_site_radius double precision;
BEGIN
  SELECT * INTO v_visit FROM public.field_visits WHERE id = p_visit_id;
  IF NOT FOUND THEN RETURN; END IF;
  IF to_jsonb(v_visit) ? 'predefined_site_id' AND (to_jsonb(v_visit)->>'predefined_site_id') IS NOT NULL
     AND to_regclass('public.predefined_sites') IS NOT NULL THEN
    EXECUTE 'SELECT latitude, longitude, checkin_radius_m FROM public.predefined_sites WHERE id = $1'
      INTO latitude, longitude, v_site_radius USING (to_jsonb(v_visit)->>'predefined_site_id')::uuid;
  END IF;
  IF latitude IS NULL OR longitude IS NULL THEN
    BEGIN
      latitude := coalesce((v_visit.destination_coords->>'latitude')::double precision,
                           (v_visit.destination_coords->>'lat')::double precision);
      longitude := coalesce((v_visit.destination_coords->>'longitude')::double precision,
                            (v_visit.destination_coords->>'lng')::double precision,
                            (v_visit.destination_coords->>'lon')::double precision);
    EXCEPTION WHEN others THEN
      latitude := NULL; longitude := NULL;
    END;
  END IF;
  radius_m := greatest(25, least(coalesce(v_site_radius,
    (to_jsonb(v_visit)->>'checkin_radius_m')::double precision,
    (to_jsonb(v_visit)->>'arrival_radius_m')::double precision, 100), 1000));
END;
$$;

-- from supabase/migrations/20261008190000_location_precision_phase2.sql
CREATE OR REPLACE FUNCTION public.hrms_site_relation(
  p_visit_id uuid, p_latitude double precision, p_longitude double precision, p_accuracy_m double precision
) RETURNS jsonb
LANGUAGE plpgsql
STABLE
SET search_path = public, pg_temp
AS $$
DECLARE
  v_site record;
  v_visit public.field_visits%rowtype;
  v_distance double precision;
  v_arrived boolean;
BEGIN
  SELECT * INTO v_site FROM public.hrms_field_visit_site(p_visit_id);
  SELECT * INTO v_visit FROM public.field_visits WHERE id = p_visit_id;
  IF v_site.latitude IS NULL OR v_site.longitude IS NULL OR p_latitude IS NULL OR p_longitude IS NULL THEN
    RETURN jsonb_build_object('state', 'UNKNOWN');
  END IF;
  v_distance := public.tracking_distance_metres(v_site.latitude, v_site.longitude, p_latitude, p_longitude);
  v_arrived := v_visit.status = 'CHECKED_IN' OR v_visit.arrived_at IS NOT NULL;
  RETURN jsonb_build_object(
    'state', CASE
      WHEN v_distance - least(coalesce(p_accuracy_m, 100), 50) <= v_site.radius_m THEN 'AT_SITE'
      WHEN v_distance - coalesce(p_accuracy_m, 0) > v_site.radius_m + 100 THEN
        CASE WHEN v_arrived THEN 'LEFT_SITE' ELSE 'APPROACHING' END
      ELSE 'NEAR_SITE' END,
    'distance_m', round(v_distance::numeric, 1),
    'radius_m', v_site.radius_m);
END;
$$;

-- from supabase/migrations/20261008180000_location_reliability_phase1.sql
CREATE FUNCTION public.rpc_latest_location_pings(p_business_date date DEFAULT NULL)
RETURNS TABLE (
  user_id        uuid,
  latitude       double precision,
  longitude      double precision,
  recorded_at    timestamptz,
  accuracy       double precision,
  provider       text,
  quality_status text,
  speed          double precision,
  last_seen_at   timestamptz,
  last_seen_quality text
)
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
DECLARE
  v_uid  uuid := auth.uid();
  v_day  date := coalesce(p_business_date, (now() AT TIME ZONE 'Asia/Kolkata')::date);
  v_from timestamptz := (v_day::text || ' 00:00')::timestamp AT TIME ZONE 'Asia/Kolkata';
  v_to   timestamptz := ((v_day + 1)::text || ' 00:00')::timestamp AT TIME ZONE 'Asia/Kolkata';
  v_all  boolean;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'AUTHENTICATION_REQUIRED' USING ERRCODE = '42501';
  END IF;

  v_all := public.hrms_is_admin_user(v_uid) OR EXISTS (
    SELECT 1 FROM public.user_permissions up
    WHERE up.user_id = v_uid AND up.revoked_at IS NULL AND (up.expires_at IS NULL OR up.expires_at > now())
      AND up.scope::text = 'GLOBAL'
      AND up.permission IN ('live_tracking.view', 'attendance.view'));

  RETURN QUERY
    WITH visible AS (
      SELECT p.id FROM public.profiles p WHERE v_all
      UNION SELECT v_uid
      UNION SELECT public.authorized_user_ids('live_tracking.view')
      UNION SELECT public.authorized_user_ids('attendance.view')
    )
    -- A stationary person's newest position is often heartbeat-only (not
    -- stored as a new row): use it when it is newer than the stored point.
    SELECT v.id,
           CASE WHEN hb.newer THEN hb.last_fix_latitude ELSE l.latitude::double precision END,
           CASE WHEN hb.newer THEN hb.last_fix_longitude ELSE l.longitude::double precision END,
           CASE WHEN hb.newer THEN hb.last_fix_at ELSE public.hrms_timestamp(l.recorded_at) END,
           CASE WHEN hb.newer THEN hb.last_fix_accuracy_m ELSE l.accuracy::double precision END,
           CASE WHEN hb.newer THEN hb.last_provider ELSE l.provider::text END,
           CASE WHEN hb.newer THEN 'RELIABLE' ELSE coalesce(l.quality_status, 'RELIABLE')::text END,
           CASE WHEN hb.newer THEN hb.last_fix_speed_mps ELSE l.speed::double precision END,
           hb.last_seen_at,
           hb.last_quality_status
    FROM visible v
    JOIN LATERAL (
      SELECT lt.latitude, lt.longitude, lt.recorded_at, lt.accuracy, lt.provider, lt.quality_status, lt.speed
      FROM public.location_tracking lt
      WHERE lt.user_id = v.id
        AND lt.recorded_at >= v_from - interval '1 day'
        AND lt.recorded_at <  v_to + interval '1 day'
        AND public.hrms_timestamp(lt.recorded_at) >= v_from
        AND public.hrms_timestamp(lt.recorded_at) <  v_to
        AND lt.latitude IS NOT NULL AND lt.longitude IS NOT NULL
        AND coalesce(lt.quality_status, 'RELIABLE') <> 'MOCKED'
      -- a RELIABLE point always wins over a newer jump / low-accuracy point
      ORDER BY (coalesce(lt.quality_status, 'RELIABLE') = 'RELIABLE') DESC, lt.recorded_at DESC
      LIMIT 1
    ) l ON true
    LEFT JOIN LATERAL (
      SELECT s.last_seen_at, s.last_quality_status, s.last_provider,
             s.last_fix_at, s.last_fix_latitude, s.last_fix_longitude, s.last_fix_accuracy_m, s.last_fix_speed_mps,
             (s.last_fix_at IS NOT NULL AND s.last_fix_latitude IS NOT NULL
              AND s.last_fix_at >= v_from AND s.last_fix_at < v_to
              AND (coalesce(l.quality_status, 'RELIABLE') <> 'RELIABLE'
                   OR s.last_fix_at > public.hrms_timestamp(l.recorded_at))) AS newer
      FROM public.tracking_sessions s
      WHERE s.user_id = v.id AND s.started_at >= v_from - interval '1 day'
        AND s.last_seen_at IS NOT NULL
      ORDER BY s.last_seen_at DESC
      LIMIT 1
    ) hb ON true;
END;
$$;

-- from supabase/migrations/20261008100000_production_integrity_phase_a.sql
CREATE OR REPLACE FUNCTION public.hrms_evaluate_office_geofence(p_client_event_id uuid)
RETURNS void
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
DECLARE
  v_ping public.location_tracking%rowtype;
  v_att public.attendance_logs%rowtype;
  v_office record;
  v_radius double precision;
  v_distance double precision;
  v_outside boolean;
  v_event public.geofence_events%rowtype;
  v_at timestamptz;
BEGIN
  SELECT * INTO v_ping FROM public.location_tracking WHERE client_event_id = p_client_event_id LIMIT 1;
  IF NOT FOUND OR v_ping.quality_status <> 'RELIABLE' OR v_ping.field_visit_id IS NOT NULL THEN RETURN; END IF;
  v_at := public.hrms_timestamp(v_ping.recorded_at);

  SELECT a.* INTO v_att FROM public.tracking_sessions s
  JOIN public.attendance_logs a ON a.id = s.attendance_log_id
  WHERE s.id = v_ping.tracking_session_id;
  IF NOT FOUND OR v_att.checkout_time IS NOT NULL OR v_att.office_id IS NULL THEN RETURN; END IF;

  -- Field staff and WFH days are not office-bound.
  IF EXISTS (SELECT 1 FROM public.field_visits fv WHERE fv.user_id = v_att.user_id AND fv.date = v_att.date) THEN RETURN; END IF;
  IF EXISTS (SELECT 1 FROM public.leave_requests lr
             WHERE lr.user_id = v_att.user_id AND lower(lr.status) = 'approved'
               AND v_att.date BETWEEN lr.start_date AND lr.end_date) THEN RETURN; END IF;

  SELECT o.id, o.name, o.latitude, o.longitude, coalesce(o.allowed_radius_meters, o.attendance_radius) AS radius
  INTO v_office FROM public.offices o WHERE o.id = v_att.office_id;
  IF NOT FOUND OR v_office.latitude IS NULL OR v_office.longitude IS NULL THEN RETURN; END IF;
  v_radius := greatest(coalesce(v_office.radius, 200), 50);
  v_distance := public.tracking_distance_metres(v_office.latitude, v_office.longitude, v_ping.latitude, v_ping.longitude);
  v_outside := (v_distance - coalesce(v_ping.accuracy, 0)) > v_radius + 150;

  SELECT * INTO v_event FROM public.geofence_events
  WHERE attendance_id = v_att.id AND geofence_type = 'OFFICE' AND geofence_id = v_office.id
    AND status NOT IN ('RETURNED_INSIDE', 'CLOSED')
  ORDER BY detected_at DESC LIMIT 1;

  IF v_outside THEN
    IF v_event.id IS NULL THEN
      INSERT INTO public.geofence_events (
        client_event_id, user_id, attendance_id, geofence_type, geofence_id, event_type,
        latitude, longitude, accuracy_m, accuracy_class, calculated_distance_m,
        event_source, detected_at, status
      ) VALUES (
        p_client_event_id, v_att.user_id, v_att.id, 'OFFICE', v_office.id, 'OFFICE_EXIT',
        v_ping.latitude, v_ping.longitude, v_ping.accuracy,
        CASE WHEN coalesce(v_ping.accuracy, 999) <= 50 THEN 'GOOD' ELSE 'UNCERTAIN' END,
        round(v_distance::numeric, 1), 'BACKGROUND_LOCATION', v_at, 'POTENTIAL_EXIT'
      ) ON CONFLICT DO NOTHING;
    ELSIF v_event.status = 'POTENTIAL_EXIT' AND v_at >= v_event.detected_at + interval '10 minutes' THEN
      PERFORM public.hrms_confirm_office_exit(v_event.id, v_distance);
    END IF;
  ELSIF v_event.id IS NOT NULL AND v_event.status = 'POTENTIAL_EXIT' THEN
    UPDATE public.geofence_events SET status = 'RETURNED_INSIDE', processed_at = now() WHERE id = v_event.id;
  END IF;
EXCEPTION WHEN others THEN
  RAISE WARNING 'office geofence skipped: %', SQLERRM;
END;
$$;

-- from supabase/migrations/20261008100000_production_integrity_phase_a.sql
CREATE OR REPLACE FUNCTION public.hrms_confirm_office_exit(p_event_id uuid, p_distance double precision DEFAULT NULL)
RETURNS void
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
DECLARE
  v_event public.geofence_events%rowtype;
  v_name text;
  v_office text;
  v_dist integer;
BEGIN
  UPDATE public.geofence_events
  SET status = 'PENDING_REASON', processed_at = now(), notification_sent_at = now(),
      calculated_distance_m = coalesce(round(p_distance::numeric, 1), calculated_distance_m)
  WHERE id = p_event_id AND status = 'POTENTIAL_EXIT'
  RETURNING * INTO v_event;
  IF NOT FOUND THEN RETURN; END IF;

  SELECT p.name, o.name INTO v_name, v_office
  FROM public.profiles p LEFT JOIN public.offices o ON o.id = v_event.geofence_id
  WHERE p.id = v_event.user_id;
  v_dist := round(coalesce(v_event.calculated_distance_m, 0))::int;

  INSERT INTO public.location_alerts (user_id, alert_type, message)
  VALUES (v_event.user_id, 'geofence_exit',
          coalesce(v_name, 'Employee') || ' has been outside ' || coalesce(v_office, 'the office')
          || ' for over 10 minutes (' || v_dist || ' m away).');

  PERFORM public.enqueue_hrms_notification(v_event.user_id,
    'You are outside the office',
    'You have been away from ' || coalesce(v_office, 'the office') || ' for over 10 minutes. Please tell us why.',
    'geofence_reason_required', 'geofence-reason:' || v_event.id,
    '/HRMS/?geofenceEvent=' || v_event.id, NULL, NULL,
    jsonb_build_object('geofenceEventId', v_event.id, 'distance', v_dist));

  PERFORM public.hrms_notify_line_and_hr(v_event.user_id,
    'Employee outside office',
    coalesce(v_name, 'An employee') || ' has been outside ' || coalesce(v_office, 'the office')
      || ' for over 10 minutes (' || v_dist || ' m away).',
    'geofence_exit', 'geofence-exit:' || v_event.id, '/HRMS/admin/live-tracking',
    jsonb_build_object('geofenceEventId', v_event.id, 'userId', v_event.user_id));
EXCEPTION WHEN others THEN
  RAISE WARNING 'office exit confirmation skipped: %', SQLERRM;
END;
$$;

-- from supabase/migrations/20261008100000_production_integrity_phase_a.sql
CREATE OR REPLACE FUNCTION public.rpc_my_pending_geofence_reason()
RETURNS jsonb
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
  SELECT coalesce((
    SELECT jsonb_build_object('id', g.id, 'distance', coalesce(g.calculated_distance_m, 0),
                              'detected_at', g.detected_at, 'office_name', o.name)
    FROM public.geofence_events g
    LEFT JOIN public.offices o ON o.id = g.geofence_id
    WHERE g.user_id = auth.uid() AND g.status = 'PENDING_REASON'
      AND NOT EXISTS (SELECT 1 FROM public.geofence_reasons gr WHERE gr.geofence_event_id = g.id)
    ORDER BY g.detected_at DESC LIMIT 1), 'null'::jsonb);
$$;

-- from supabase/migrations/20261008100000_production_integrity_phase_a.sql
CREATE FUNCTION public.rpc_submit_geofence_reason(p_event_id uuid, p_reason text)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
DECLARE
  v_event public.geofence_events%rowtype;
  v_reason_id uuid;
  v_name text;
BEGIN
  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'AUTHENTICATION_REQUIRED'; END IF;
  IF length(btrim(coalesce(p_reason, ''))) < 10 THEN RAISE EXCEPTION 'REASON_TOO_SHORT'; END IF;
  SELECT * INTO v_event FROM public.geofence_events WHERE id = p_event_id FOR UPDATE;
  IF NOT FOUND OR v_event.user_id <> auth.uid() THEN RAISE EXCEPTION 'EVENT_NOT_FOUND'; END IF;
  IF EXISTS (SELECT 1 FROM public.geofence_reasons WHERE geofence_event_id = p_event_id) THEN
    RAISE EXCEPTION 'REASON_ALREADY_SUBMITTED';
  END IF;

  INSERT INTO public.geofence_reasons (geofence_event_id, submitted_by, reason)
  VALUES (p_event_id, auth.uid(), left(btrim(p_reason), 1000))
  RETURNING id INTO v_reason_id;
  UPDATE public.geofence_events SET status = 'REASON_SUBMITTED', processed_at = now() WHERE id = p_event_id;

  SELECT name INTO v_name FROM public.profiles WHERE id = auth.uid();
  PERFORM public.hrms_notify_line_and_hr(auth.uid(), 'Reason submitted for leaving office',
    coalesce(v_name, 'An employee') || ': ' || left(btrim(p_reason), 140),
    'geofence_reason_submitted', 'geofence-reason-submitted:' || p_event_id, '/HRMS/admin/live-tracking',
    jsonb_build_object('geofenceEventId', p_event_id, 'reasonId', v_reason_id));
  RETURN jsonb_build_object('success', true, 'reason_id', v_reason_id);
END;
$$;

-- from supabase/migrations/20261008100000_production_integrity_phase_a.sql
CREATE OR REPLACE FUNCTION public.rpc_geofence_review_queue(p_days integer DEFAULT 7)
RETURNS jsonb
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
  SELECT coalesce(jsonb_agg(row_to_json(q) ORDER BY q.detected_at DESC), '[]'::jsonb)
  FROM (
    SELECT g.id, g.user_id, p.name AS employee_name, o.name AS office_name, g.status,
           g.detected_at, g.calculated_distance_m AS distance_m, g.accuracy_m,
           g.latitude, g.longitude,
           (SELECT gr.reason FROM public.geofence_reasons gr WHERE gr.geofence_event_id = g.id
            ORDER BY gr.submitted_at DESC LIMIT 1) AS reason,
           (SELECT gr.submitted_at FROM public.geofence_reasons gr WHERE gr.geofence_event_id = g.id
            ORDER BY gr.submitted_at DESC LIMIT 1) AS reason_at
    FROM public.geofence_events g
    JOIN public.profiles p ON p.id = g.user_id
    LEFT JOIN public.offices o ON o.id = g.geofence_id
    WHERE g.status IN ('PENDING_REASON', 'REASON_SUBMITTED')
      AND g.detected_at >= now() - make_interval(days => greatest(1, least(coalesce(p_days, 7), 60)))
      AND g.user_id <> auth.uid()
      AND (public.is_profile_admin() OR public.can_access_user_data(g.user_id, 'live_tracking.view'))
    LIMIT 200
  ) q;
$$;

-- from supabase/migrations/20261008180000_location_reliability_phase1.sql
CREATE OR REPLACE FUNCTION public.hrms_geofence_sweep()
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
DECLARE
  r record;
  v_fix record;
  v_office record;
  v_radius double precision;
  v_distance double precision;
  v_outside boolean;
  v_confirmed integer := 0;
  v_returned integer := 0;
  v_unverified integer := 0;
  v_closed integer := 0;
BEGIN
  UPDATE public.geofence_events g
  SET status = 'CLOSED', processed_at = now(), resolution = coalesce(g.resolution, 'CHECKED_OUT')
  FROM public.attendance_logs a
  WHERE a.id = g.attendance_id AND a.checkout_time IS NOT NULL
    AND g.status = 'POTENTIAL_EXIT';
  GET DIAGNOSTICS v_closed = ROW_COUNT;

  FOR r IN
    SELECT g.id, g.user_id, g.attendance_id, g.geofence_id, g.detected_at
    FROM public.geofence_events g
    JOIN public.attendance_logs a ON a.id = g.attendance_id AND a.checkout_time IS NULL
    WHERE g.status = 'POTENTIAL_EXIT' AND g.geofence_type = 'OFFICE'
      AND g.detected_at <= now() - interval '10 minutes'
      AND g.detected_at >= now() - interval '1 day'
  LOOP
    -- Newest real (RELIABLE) fix of this attendance, stored or heartbeat-only.
    SELECT s.last_fix_at, s.last_fix_latitude, s.last_fix_longitude, s.last_fix_accuracy_m
    INTO v_fix
    FROM public.tracking_sessions s
    WHERE s.attendance_log_id = r.attendance_id AND s.last_fix_at IS NOT NULL
    ORDER BY s.last_fix_at DESC LIMIT 1;

    SELECT o.latitude, o.longitude, coalesce(o.allowed_radius_meters, o.attendance_radius) AS radius
    INTO v_office FROM public.offices o WHERE o.id = r.geofence_id;

    IF v_fix.last_fix_at IS NOT NULL AND v_fix.last_fix_at > r.detected_at
       AND v_office.latitude IS NOT NULL AND v_office.longitude IS NOT NULL THEN
      v_radius := greatest(coalesce(v_office.radius, 200), 50);
      v_distance := public.tracking_distance_metres(v_office.latitude, v_office.longitude,
                                                     v_fix.last_fix_latitude, v_fix.last_fix_longitude);
      v_outside := (v_distance - coalesce(v_fix.last_fix_accuracy_m, 0)) > v_radius + 150;
      IF v_outside AND v_fix.last_fix_at >= r.detected_at + interval '10 minutes' THEN
        PERFORM public.hrms_confirm_office_exit(r.id, v_distance);      -- 2nd outside fix, 10+ min later
        v_confirmed := v_confirmed + 1;
      ELSIF NOT v_outside THEN
        UPDATE public.geofence_events SET status = 'RETURNED_INSIDE', processed_at = now()
        WHERE id = r.id AND status = 'POTENTIAL_EXIT';
        v_returned := v_returned + 1;
      END IF;
    ELSIF r.detected_at <= now() - interval '30 minutes' THEN
      -- One outside reading and then no location at all: not evidence of an
      -- exit. Silence is handled by the tracking-silence alerts instead.
      UPDATE public.geofence_events
      SET status = 'CLOSED', processed_at = now(), resolution = 'UNVERIFIED_NO_DATA'
      WHERE id = r.id AND status = 'POTENTIAL_EXIT';
      v_unverified := v_unverified + 1;
    END IF;
  END LOOP;
  RETURN jsonb_build_object('confirmed', v_confirmed, 'returned', v_returned,
                            'unverified', v_unverified, 'closed', v_closed);
END;
$$;

-- from supabase/migrations/20260810000000_field_event_audience_context_notifications.sql
create or replace function public.sync_field_visit_arrival_attendance(p_visit_id uuid)
returns uuid language plpgsql security definer set search_path=public,pg_temp as $$
declare v_visit public.field_visits%rowtype;v_attendance public.attendance_logs%rowtype;
  v_lat double precision;v_lon double precision;v_distance integer;
begin
  select * into v_visit from public.field_visits where id=p_visit_id;
  if not found or v_visit.checkin_time is null then raise exception 'FIELD_VISIT_ARRIVAL_REQUIRED'; end if;
  v_lat:=nullif(v_visit.checkin_location->>'latitude','')::double precision;
  v_lon:=nullif(v_visit.checkin_location->>'longitude','')::double precision;
  v_distance:=round(coalesce(v_visit.arrival_distance_metres,
    nullif(v_visit.checkin_location->>'distance_metres','')::double precision,0));
  perform pg_advisory_xact_lock(hashtextextended(v_visit.user_id::text||':'||v_visit.date::text,0));
  select * into v_attendance from public.attendance_logs
    where user_id=v_visit.user_id and date=v_visit.date order by checkin_time nulls last limit 1 for update;
  if found then
    update public.attendance_logs set
      checkin_time=coalesce(checkin_time,v_visit.checkin_time),
      attendance_type=case when checkin_time is null then 'FIELD_VISIT' else attendance_type end,
      checkin_source=case when checkin_time is null then 'FIELD_VISIT' else checkin_source end,
      checkin_status=case when checkin_time is null then 'FIELD_VISIT' else checkin_status end,
      checkin_location=case when checkin_time is null then v_visit.checkin_location else checkin_location end,
      checkin_latitude=case when checkin_time is null then v_lat else checkin_latitude end,
      checkin_longitude=case when checkin_time is null then v_lon else checkin_longitude end,
      checkin_location_name=case when checkin_time is null then coalesce(v_visit.project_name,v_visit.location_name) else checkin_location_name end,
      checkin_distance_meters=case when checkin_time is null then v_distance else checkin_distance_meters end,
      attendance_context='FIELD_VISIT',field_visit_id=v_visit.id,
      context_location_name=coalesce(v_visit.project_name,v_visit.location_name),context_started_at=v_visit.checkin_time,
      attendance_state='ON_FIELD_VISIT',attendance_status='PRESENT',day_status='P',
      status=case when checkout_time is null then 'CHECKED_IN' else status end,updated_at=now()
    where id=v_attendance.id returning * into v_attendance;
  else
    insert into public.attendance_logs(user_id,date,attendance_type,attendance_status,day_status,
      checkin_time,checkin_source,checkin_status,checkin_location,checkin_latitude,checkin_longitude,
      checkin_location_name,checkin_distance_meters,status,attendance_state,attendance_context,
      field_visit_id,context_location_name,context_started_at,auto_checkout,notes)
    values(v_visit.user_id,v_visit.date,'FIELD_VISIT','PRESENT','P',v_visit.checkin_time,
      'FIELD_VISIT','FIELD_VISIT',v_visit.checkin_location,v_lat,v_lon,
      coalesce(v_visit.project_name,v_visit.location_name),v_distance,'CHECKED_IN','ON_FIELD_VISIT',
      'FIELD_VISIT',v_visit.id,coalesce(v_visit.project_name,v_visit.location_name),v_visit.checkin_time,false,
      'Direct field visit attendance: '||v_visit.location_name||'.') returning * into v_attendance;
  end if;
  return v_attendance.id;
exception when unique_violation then
  select * into v_attendance from public.attendance_logs where user_id=v_visit.user_id and date=v_visit.date limit 1;
  update public.attendance_logs set attendance_context='FIELD_VISIT',field_visit_id=v_visit.id,
    context_location_name=coalesce(v_visit.project_name,v_visit.location_name),context_started_at=v_visit.checkin_time,
    attendance_state='ON_FIELD_VISIT',updated_at=now() where id=v_attendance.id;
  return v_attendance.id;
end $$;

-- from supabase/migrations/20261008140000_fix_another_visit_in_progress.sql
CREATE OR REPLACE FUNCTION public.hrms_close_open_field_visits_before_today(p_user_id uuid DEFAULT NULL)
RETURNS integer
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
DECLARE
  v_today date := (now() AT TIME ZONE 'Asia/Kolkata')::date;
  r record;
  v_count integer := 0;
BEGIN
  FOR r IN
    SELECT id, date FROM public.field_visits
    WHERE status = 'CHECKED_IN' AND checkout_time IS NULL
      AND date < v_today
      AND (p_user_id IS NULL OR user_id = p_user_id)
    FOR UPDATE
  LOOP
    UPDATE public.field_visits
    SET checkout_time = public.hrms_auto_checkout_at(r.date),
        status = 'COMPLETED', visit_state = 'COMPLETED', journey_status = 'COMPLETED',
        auto_closed = true
    WHERE id = r.id;
    PERFORM public.hrms_apply_field_visit_risk(r.id);
    v_count := v_count + 1;
  END LOOP;
  RETURN v_count;
END;
$$;

-- from supabase/migrations/20261001000000_multi_office_attendance_and_permissions.sql
CREATE OR REPLACE FUNCTION public.trg_populate_biometric_log_office()
RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
IF NEW.office_id IS NULL AND NEW.serial_number IS NOT NULL THEN
SELECT bd.office_id INTO NEW.office_id
FROM public.biometric_devices bd
WHERE bd.device_identifier = NEW.serial_number
AND bd.status = 'ACTIVE'
LIMIT 1;
END IF;
RETURN NEW;
END;
$$;

RESET check_function_bodies;
CREATE TRIGGER trg_biometric_log_office BEFORE INSERT ON public.smartoffice_device_logs
  FOR EACH ROW EXECUTE FUNCTION public.trg_populate_biometric_log_office();
